xml.Script:
        clRed      := 'C80000';
        clWhite    := 'FFFFFF';
        clGold     := 'BF8040';
        clGreen    := '005600';
        clBlue     := '000078';
        clLavender := '8661C6';
        
        Colors[ 0] := clGold;
        Colors[ 1] := clGreen;
        Colors[ 2] := clLavender;
        Colors[ 3] := clBlue;
        Colors[ 4] := clBlue;
        Colors[ 5] := clWhite;
        Colors[ 6] := clRed;
        Colors[ 7] := clLavender;
        Colors[ 8] := clRed;
        Colors[ 9] := clGreen;
        Colors[10] := clWhite;
        Colors[11] := clGold;
        
        W := 1 / 2;
        D := W / 3;

        Vx[ 0] := -W; Vy[ 0] := -W; Vz[ 0] := -W;
        Vx[ 1] := -W; Vy[ 1] := -W; Vz[ 1] :=  W;
        Vx[ 2] := -W; Vy[ 2] :=  W; Vz[ 2] := -W;
        Vx[ 3] := -W; Vy[ 3] :=  W; Vz[ 3] :=  W;
        Vx[ 4] :=  W; Vy[ 4] := -W; Vz[ 4] := -W;
        Vx[ 5] :=  W; Vy[ 5] := -W; Vz[ 5] :=  W;
        Vx[ 6] :=  W; Vy[ 6] :=  W; Vz[ 6] := -W;
        Vx[ 7] :=  W; Vy[ 7] :=  W; Vz[ 7] :=  W;
        
        Ax[ 0] :=  W; Ay[ 0] :=  D; Az[ 0] :=  0;
        Ax[ 1] :=  W; Ay[ 1] := -D; Az[ 1] :=  0;
        
        Ax[ 2] := -W; Ay[ 2] :=  D; Az[ 2] :=  0;
        Ax[ 3] := -W; Ay[ 3] := -D; Az[ 3] :=  0;
        
        Ax[ 4] :=  0; Ay[ 4] :=  W; Az[ 4] :=  D;
        Ax[ 5] :=  0; Ay[ 5] :=  W; Az[ 5] := -D;
        
        Ax[ 6] :=  0; Ay[ 6] := -W; Az[ 6] :=  D;
        Ax[ 7] :=  0; Ay[ 7] := -W; Az[ 7] := -D;
        
        Ax[ 8] :=  D; Ay[ 8] :=  0; Az[ 8] :=  W;
        Ax[ 9] := -D; Ay[ 9] :=  0; Az[ 9] :=  W;
        
        Ax[10] :=  D; Ay[10] :=  0; Az[10] := -W;
        Ax[11] := -D; Ay[11] :=  0; Az[11] := -W;
